                    sortedwords.insert(0, None)
                if len(sortedwords) > 0 and len(word) > len(sortedwords[-1]):
                    sortedwords.append(word)
                elif len(sortedwords) > 0 and len(word) == len(sortedwords[-1]):
                    idx = len(sortedwords) - 1
                    while idx > 0 and words[idx - 1] > word:
