                        idx += 1
                    sortedwords.insert(idx, word)
            elif len(word) > word_length and word_length == len(sortedwords) + 1:
                temp_list.append(word)
        sortedwords = temp_list + [x for x in sortedwords if x is not None]
        word_length += 1
    return sortedwords
